<?php require 'config.php'; role(['admin','kasir']);$id=(int)($_GET['id']??0);$t=$conn->query("SELECT t.*,u.name cashier FROM transactions t JOIN users u ON u.id=t.user_id WHERE t.id=$id")->fetch_assoc();if(!$t)die('Transaksi tidak ditemukan');$ds=$conn->query("SELECT d.*,m.name FROM transaction_details d JOIN menus m ON m.id=d.menu_id WHERE d.transaction_id=$id");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$t['invoice_code']?> • RestoPOS</title>
<link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🍽️</text></svg>"><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet"><style>body{background:#f5f7fb;font-family:Poppins,sans-serif;margin:0}.receipt{width:380px;max-width:92vw;background:#fff;margin:35px auto;padding:28px;border-radius:18px;box-shadow:0 12px 35px #1e293b12}.center{text-align:center}.logo{font-size:24px;font-weight:700}.muted{font-size:10px;color:#8a95a8}.line{border:0;border-top:1px dashed #ccd3df;margin:17px 0}.r{display:flex;justify-content:space-between;gap:15px;font-size:11px;margin:9px 0}.total{font-size:15px;font-weight:700}.actions{display:flex;gap:8px;margin-bottom:18px}.btn{flex:1;padding:10px;border:0;border-radius:9px;font-weight:600;cursor:pointer}.primary{background:#2563eb;color:#fff}.light{background:#eef2f7}@media print{body{background:#fff}.receipt{box-shadow:none;margin:0;width:300px;padding:10px}.actions{display:none}}</style></head><body><div class="receipt"><div class="actions"><button class="btn primary" onclick="print()">Cetak Struk</button><button class="btn light" onclick="location.href='index.php'">Dashboard</button></div><div class="center"><div class="logo">RestoPOS</div><div class="muted">Point of Sale • Restoran</div></div><hr class="line"><div class="r"><span><?=$t['invoice_code']?></span><span><?=date('d/m/Y H:i',strtotime($t['created_at']))?></span></div><div class="r"><span>Kasir</span><span><?=$t['cashier']?></span></div><hr class="line"><?php while($d=$ds->fetch_assoc()):?><div class="r"><span><?=$d['name']?> x<?=$d['qty']?></span><span><?=number_format($d['subtotal'],0,',','.')?></span></div><?php endwhile;?><hr class="line"><div class="r total"><span>Total</span><span><?=number_format($t['total_amount'],0,',','.')?></span></div><div class="r"><span>Bayar</span><span><?=number_format($t['pay_amount'],0,',','.')?></span></div><div class="r"><span>Kembali</span><span><?=number_format($t['change_amount'],0,',','.')?></span></div><hr class="line"><div class="center muted">Terima kasih 🙏<br>Semoga puas dengan pelayanan kami.</div></div></body></html>